export function normalizeStateName(inputName: string): string {
  if (!inputName) return '';
  const clean = inputName.trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  return clean;
}

export function findStateFeature(stateName: string): StateMapFeature | undefined {
  if (!stateName) return undefined;
  const targetNorm = normalizeStateName(stateName);
  
  return INDIA_STATE_FEATURES.find(s => {
    if (normalizeStateName(s.name) === targetNorm) return true;
    if (s.id.toLowerCase() === targetNorm) return true;
    return s.aliases.some(alias => normalizeStateName(alias) === targetNorm);
  });
}
